import { useEffect, useRef, useState } from 'react';
import './Navigation.css';
import LogoCrest from './LogoCrest';
import * as Scroll from 'react-scroll';

const SCROLL_DELTA = 8;
const TOP_REVEAL_Y = 60;

const NAV_LINKS = [
  { to: 'workScroll', label: 'Work' },
  { to: 'skillsScroll', label: 'Skills' },
  { to: 'aboutScroll', label: 'About' },
  { to: 'prizmaScroll', label: 'Prizma' },
];

function Navigation() {
  const ScrollLink = Scroll.Link;
  const [logoSpinKey, setLogoSpinKey] = useState(0);
  const [showMenu, setShowMenu] = useState(false);
  const [navHidden, setNavHidden] = useState(false);
  const menuButtonRef = useRef(null);
  const menuRef = useRef(null);
  const desktopNavRef = useRef(null);
  const mobileNavRef = useRef(null);

  useEffect(() => {
    let lastScrollY = window.scrollY;

    const onScroll = () => {
      const currentScrollY = window.scrollY;
      const scrollDelta = currentScrollY - lastScrollY;
      const activeEl = document.activeElement;
      const focusInsideNav =
        (desktopNavRef.current && desktopNavRef.current.contains(activeEl)) ||
        (mobileNavRef.current && mobileNavRef.current.contains(activeEl));

      if (focusInsideNav || currentScrollY <= TOP_REVEAL_Y) {
        setNavHidden(false);
      } else if (scrollDelta > SCROLL_DELTA) {
        setNavHidden(true);
        setShowMenu(false);
      } else if (scrollDelta < -SCROLL_DELTA) {
        setNavHidden(false);
      }

      lastScrollY = currentScrollY;
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  useEffect(() => {
    if (!showMenu) return undefined;

    const onKeyDown = (event) => {
      if (event.key === 'Escape') {
        setShowMenu(false);
        menuButtonRef.current?.focus();
      }
    };

    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [showMenu]);

  const spinLogo = () => {
    setLogoSpinKey((prev) => prev + 1);
  };

  const handleNavClick = () => {
    spinLogo();
    setShowMenu(false);
  };

  const toggleMenu = () => {
    setShowMenu((prev) => !prev);
  };

  const renderNavLink = (link, className = 'aboutLink') => (
    <ScrollLink
      key={link.to}
      to={link.to}
      href={`#${link.to}`}
      spy={true}
      smooth={true}
      duration={500}
      offset={-100}
      isDynamic={true}
      className={className}
      activeClass="aboutLinkActive"
      onClick={handleNavClick}
    >
      {link.label}
    </ScrollLink>
  );

  return (
    <>
      <nav
        className={`navBar${navHidden ? ' navBarHidden' : ''}`}
        aria-label="Primary"
        ref={desktopNavRef}
      >
        <div className="navContent">
          {NAV_LINKS.slice(0, 2).map((link) => renderNavLink(link))}
          <div id="logoNameDiv">
            <LogoCrest />
          </div>
          {NAV_LINKS.slice(2).map((link) => renderNavLink(link))}
        </div>
      </nav>

      <nav
        className={`navBarSmall${navHidden ? ' navBarHidden' : ''}`}
        aria-label="Mobile"
        ref={mobileNavRef}
      >
        <div className="navContentSmall">
          <button
            type="button"
            id="logoMenu"
            ref={menuButtonRef}
            aria-expanded={showMenu}
            aria-controls="menuContents"
            aria-label={showMenu ? 'Close menu' : 'Open menu'}
            onClick={toggleMenu}
          >
            <LogoCrest key={logoSpinKey} />
          </button>
          {showMenu && (
            <div id="menuContents" ref={menuRef}>
              {NAV_LINKS.map((link) =>
                renderNavLink(
                  link,
                  link.to === 'skillsScroll' ? 'skillsLink' : 'aboutLink'
                )
              )}
            </div>
          )}
        </div>
      </nav>
    </>
  );
}

export default Navigation;
